  bar.position.set(0, 1.55, -0.2);
  group.add(bar);
  const bar2 = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.18, 0.42), new THREE.MeshBasicMaterial({ color: 0x2244ff }));
  bar2.position.set(0.7, 1.55, -0.2);
  group.add(bar2);
  group.position.set(x, 0, z);
